<?php

namespace App\Services\Lead;

use App\Models\DispositionConfigMongo;
use App\Models\DispositionLogMongo;
use App\Models\PlatformData;
use App\Models\PlatformDataItem;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Faker\Factory as Faker;

class LeadFilterService
{

    public function getFilterLeadsV2(Request $request)
    {

        set_time_limit(0);
        ini_set('memory_limit', -1);

        DispositionLogMongo::truncate();
        DispositionConfigMongo::truncate();

        $userId = auth()->id();
        $dummyConditions = $this->generateDummyConditions();

        DB::statement("
            CREATE TEMPORARY TABLE temp_conditions (
                phone VARCHAR(255) COLLATE utf8mb4_unicode_ci,
                lead_id VARCHAR(255) COLLATE utf8mb4_unicode_ci,
                buyer_id int,
                INDEX(phone),
                INDEX(lead_id),
                INDEX(buyer_id)
            )
        ");

        foreach (array_chunk($dummyConditions, 10000) as $chunk) {
            DB::table('temp_conditions')->insert($chunk);
            // DB::table('temp_conditions')->insert($dummyConditions);
        }

        $batchSize = 5000; // Define batch size
        $buffer = [];
        $now = now();

        $config = DispositionConfigMongo::create([
            'user_id' => $userId,
            'uid' => (string) str()->uuid()
        ]);

            $todos = PlatformData::query()
                        // ->whereIn('lead_status', ['Pending', 'Returned', 'Disqualified', 'Sent Agreement', 'Agreement Signed', 'Retained'])
                        ->whereExists(function ($query) {
                            $query->select(DB::raw(1))
                                ->from('temp_conditions as tc')
                                ->whereColumn('tc.buyer_id', 'platform_datas.buyer_id')
                                ->whereColumn('tc.phone', 'platform_datas.phone')
                                ->whereExists(function ($subQuery) {
                                    $subQuery->select(DB::raw(1))
                                        ->from('platform_data_items as pdi')
                                        ->whereColumn('pdi.value', 'tc.lead_id')
                                        ->whereColumn('platform_datas.id', 'pdi.platform_data_id');
                                });
                        })
                        ->select('platform_datas.*')
                        ->lazyById(5000)
                        ->each(function ($lead) use (&$buffer, $batchSize, $config, $now) {
                            // Transform or process the data
                            $buffer[] = [
                                            'disposition_config_id' => $config->id,
                                            'platform_data_id' => $lead->id,
                                            'lead_status' => $lead->lead_status,
                                            'data' => [],
                                            'is_duplicate' => false, // Correctly detects duplicates
                                            'updatable_data' => [],
                                            'created_at' => $now,
                                            'updated_at' => $now
                                        ];
                        
                            // When batch reaches 5K, insert and clear the buffer
                            if (count($buffer) >= $batchSize) {
                                DispositionLogMongo::insert($buffer);
                                $buffer = []; // Clear the buffer
                            }
                        });

                        if (!empty($buffer)) {
                            DispositionLogMongo::insert($buffer);
                        }

        return [
            'total' => DispositionLogMongo::count(),
            'data' => DispositionLogMongo::limit(40)->get()
        ];

    }

